import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百六十二章 欢喜与贪欲的浇灌","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/262第二百六十二章 欢喜与贪欲的浇灌.md","filePath":"meditation/巴利文大藏经/262第二百六十二章 欢喜与贪欲的浇灌.md"}'),r={name:"meditation/巴利文大藏经/262第二百六十二章 欢喜与贪欲的浇灌.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百六十二章-欢喜与贪欲的浇灌",tabindex:"-1"},[l("第二百六十二章 欢喜与贪欲的浇灌 "),e("a",{class:"header-anchor",href:"#第二百六十二章-欢喜与贪欲的浇灌","aria-label":'Permalink to "第二百六十二章 欢喜与贪欲的浇灌"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"6.攀住品",-1),e("p",null,"相应部22相应53经/攀住经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），攀附、攀缠世间事物的众生就无法解脱出来，不攀附、不攀缠世间事物的众生就能解脱出来。",-1),e("p",null,"比丘们！「识」（识就是眼识、耳识、鼻识、舌识、身识、意识。眼识、耳识、鼻识、舌识、身识、意识解释，见第一百八十八章）的生起、存在。就如同树木花草栽种在大地上，要用雨露浇灌才能生长、存在一样，「识」栽种在物质事物、物质身体、感受、念想、行为、认识、分别、判断上，要用欢喜、贪欲浇灌才能生起、存在。对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起欢喜、贪欲就是攀附、攀缠。攀附、攀缠物质事物、物质身体、感受、念想、行为、认识、分别、判断就会生起「识」，就会让「识」生长、增长。",-1),e("p",null,"比丘们！如果世间有人说：「离开物质事物、物质身体、感受、念想、行为、认识、分别、判断的攀附、攀缠，不对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起欢喜、贪欲，不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，我要找到「识」的来去、生灭、增减、有无」，那是不可能的，就如同将栽种在大地上的树木花草，全部连根拔起，切割成小块，压成粉末，又用大火焚烧成灰烬后，抛入大海，这些被连根拔起，切割成小块，压成粉末，大火焚烧，抛入大海的树木花草早就无法继续生根发芽了，早就不存在了。同样的道理，如果世间人，他们除灭对色界、感受界、念想界、行为界、识界（色界解释，见第一百零三章；感受界、念想界、行为界解释，见第二百一十九章；识界就是眼识、耳识、鼻识、舌识、身识、意识，眼识、耳识、鼻识、舌识、身识、意识解释，见第一百八十八章）的贪欲，当他们对色界、感受界、念想界、行为界、识界的贪欲灭尽的时候，生起「识」的前提条件就没有了，「识」的立足点就没有了，就如同被连根拔起，切割成小块，压成粉末，大火焚烧，抛入大海的树木花草那样，早就无法继续生根发芽了，早就不存在了。没有欢喜、贪欲的浇灌，没有立足点的「识」就不会生起、成长、存在，没有「识」的产生就解脱出来。解脱后就能保持内心长久的清净安宁，内心清净安宁后就不会被世间一切的事物扰动、困惑、影响，就不会执着和挂念任何的念想，就不会生起任何的念想，没有执着，没有挂念，没有念想，就进入没有烦恼和痛苦的涅槃境界，就能彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
